   v[28] = (x[6] * x[1] + x[13] * x[8] + x[20] * x[15] + x[27] * x[22] + x[34] * x[29] + x[41] * x[36] - v[27] * v[2]) / v[3];
   v[29] = (x[6] * x[2] + x[13] * x[9] + x[20] * x[16] + x[27] * x[23] + x[34] * x[30] + x[41] * x[37] - v[27] * v[5] - v[28] * v[6]) / v[7];
