   v[32] = (x[6] * x[5] + x[13] * x[12] + x[20] * x[19] + x[27] * x[26] + x[34] * x[33] + x[41] * x[40] - v[27] * v[20] - v[28] * v[21] - v[29] * v[22] - v[30] * v[23] - v[31] * v[24]) / v[25];
